// Limpiar contador de reintentos cuando el job completa exitosamente
const markdownResult = $input.first().json;

// Obtener job ID del nodo de status check
const statusCheck = $('Check LlamaParse Status').first();
if (statusCheck && statusCheck.json && statusCheck.json.id) {
  const jobId = statusCheck.json.id;

  // Limpiar contador de este job en static data
  const staticData = $getWorkflowStaticData('node');
  if (staticData.llamaparseRetries && staticData.llamaparseRetries[jobId]) {
    console.log(`Limpiando contador de reintentos para job ${jobId}`);
    delete staticData.llamaparseRetries[jobId];
  }
}

// Pasar los datos sin modificar
return {
  json: markdownResult
};

// Controlar límite de reintentos para LlamaParse polling
const MAX_RETRIES = 10;

// Obtener datos actuales del status check
const currentData = $input.first().json;
const jobId = currentData.id;

if (!jobId) {
  throw new Error('No se encontró job ID en la respuesta de LlamaParse');
}

// Obtener workflow static data para almacenamiento persistente
const staticData = $getWorkflowStaticData('node');

// Inicializar estructura de contadores si no existe
if (!staticData.llamaparseRetries) {
  staticData.llamaparseRetries = {};
}

// Obtener o inicializar contador para este job
let retryCount = staticData.llamaparseRetries[jobId] || 0;

// Incrementar contador
retryCount++;
staticData.llamaparseRetries[jobId] = retryCount;

console.log(`Reintento LlamaParse #${retryCount}/${MAX_RETRIES} - Job: ${jobId} - Status: ${currentData.status}`);

// Si excedemos el límite, lanzar error
if (retryCount > MAX_RETRIES) {
  // Limpiar contador antes de fallar
  delete staticData.llamaparseRetries[jobId];

  throw new Error(
    `LlamaParse polling excedió el límite de ${MAX_RETRIES} reintentos. ` +
    `Último status: ${currentData.status}. Job ID: ${jobId}`
  );
}

// Pasar los datos sin modificar (el contador está en static data)
return {
  json: currentData
};

// ============================================
// NODO: Chunk Markdown
// TIPO: Code (JavaScript) v2
// FASE: I1.7
// ============================================

// ============================================
// CONFIGURACIÓN
// ============================================
const TARGET_TOKENS = 450;      // Target ideal
const MAX_TOKENS = 600;         // Límite duro
const MIN_TOKENS = 100;         // Mínimo para chunk válido
const OVERLAP_CHARS = 200;      // ~50 tokens de overlap

// ============================================
// FUNCIONES AUXILIARES
// ============================================

/**
 * Estimación de tokens (4 chars ≈ 1 token para español)
 * Más preciso que dividir por 4 para textos legales
 */
function estimateTokens(text) {
  if (!text) return 0;
  // Español tiene palabras más largas que inglés
  const words = text.split(/\s+/).length;
  const chars = text.length;
  // Fórmula híbrida: promedio entre chars/4 y words*1.3
  return Math.round((chars / 4 + words * 1.3) / 2);
}

/**
 * Detectar tipo de chunk basado en contenido
 */
function detectChunkType(content) {
  // Tabla salarial
  if (/\|.*\|/.test(content) && /salario|retribuc|sueldo|euro|€/i.test(content)) {
    return 'tabla_salarial';
  }
  // Tabla genérica
  if (/\|.*\|/.test(content)) {
    return 'tabla';
  }
  // Definiciones
  if (/se entiende por|a los efectos|definición|concepto/i.test(content)) {
    return 'definicion';
  }
  // Procedimientos
  if (/procedimiento|solicitud|plazo de|días (hábiles|naturales)/i.test(content)) {
    return 'procedimiento';
  }
  // Jornada laboral
  if (/jornada|horario|descanso|vacaciones|permiso/i.test(content)) {
    return 'jornada';
  }
  // Sanciones
  if (/falta (leve|grave|muy grave)|sanción|despido/i.test(content)) {
    return 'sanciones';
  }
  return 'normativa';
}

/**
 * Extraer sección (Capítulo) del contenido
 */
function extractSeccion(content, previousSeccion) {
  const match = content.match(/^##\s+(.+)$/m);
  if (match) return match[1].trim();
  return previousSeccion || null;
}

/**
 * Extraer artículo del contenido
 */
function extractArticulo(content, previousArticulo) {
  const match = content.match(/^###\s+(.+)$/m);
  if (match) return match[1].trim();
  // También buscar "Artículo X." en el texto
  const artMatch = content.match(/Artículo\s+\d+[º°]?\.?\s*[–\-:]?\s*([^\n]+)/i);
  if (artMatch) return artMatch[0].trim();
  return previousArticulo || null;
}

/**
 * Detectar si el chunk contiene una tabla
 */
function hasTable(content) {
  // Buscar patrón de tabla markdown: | col1 | col2 |
  const tablePattern = /\|[^\n]+\|[\s\S]*?\|[^\n]+\|/;
  return tablePattern.test(content);
}

/**
 * Extraer tabla completa del markdown
 */
function extractTable(content, startIndex) {
  const lines = content.substring(startIndex).split('\n');
  const tableLines = [];
  let inTable = false;

  for (const line of lines) {
    if (line.includes('|')) {
      tableLines.push(line);
      inTable = true;
    } else if (inTable && line.trim() === '') {
      // Fin de la tabla
      break;
    } else if (inTable) {
      // Línea sin | después de estar en tabla = fin
      break;
    }
  }

  return tableLines.join('\n');
}

/**
 * Dividir markdown preservando estructura
 */
function splitByStructure(markdown) {
  const sections = [];

  // Regex para capturar secciones completas
  // Prioridad: ## > ### > párrafos
  const sectionRegex = /^(#{2,3}\s+[^\n]+)([\s\S]*?)(?=^#{2,3}\s+|\z)/gm;

  let match;
  let lastIndex = 0;

  while ((match = sectionRegex.exec(markdown)) !== null) {
    // Texto antes de la sección (si existe)
    if (match.index > lastIndex) {
      const beforeText = markdown.substring(lastIndex, match.index).trim();
      if (beforeText) {
        sections.push({
          type: 'text',
          content: beforeText
        });
      }
    }

    // La sección completa
    sections.push({
      type: 'section',
      header: match[1],
      content: match[0].trim()
    });

    lastIndex = match.index + match[0].length;
  }

  // Texto restante
  if (lastIndex < markdown.length) {
    const remaining = markdown.substring(lastIndex).trim();
    if (remaining) {
      sections.push({
        type: 'text',
        content: remaining
      });
    }
  }

  // Si no se encontraron secciones, dividir por párrafos
  if (sections.length === 0) {
    return markdown.split(/\n\n+/).filter(p => p.trim()).map(p => ({
      type: 'text',
      content: p.trim()
    }));
  }

  return sections;
}

// ============================================
// FUNCIÓN PRINCIPAL DE CHUNKING
// ============================================

function chunkMarkdown(markdown, convenioId, convenioNombre) {
  const chunks = [];
  let chunkNumber = 0;
  let currentSeccion = null;
  let currentArticulo = null;

  // Paso 1: Dividir por estructura
  const sections = splitByStructure(markdown);

  let currentChunk = '';
  let currentTokens = 0;

  for (const section of sections) {
    const sectionContent = section.content || section;
    const sectionTokens = estimateTokens(sectionContent);

    // Actualizar tracking de sección/artículo
    const tempSeccion = extractSeccion(sectionContent, currentSeccion);
    if (tempSeccion) currentSeccion = tempSeccion;

    const tempArticulo = extractArticulo(sectionContent, currentArticulo);
    if (tempArticulo) currentArticulo = tempArticulo;

    // CASO 1: Sección tiene tabla → chunk independiente (permitir hasta MAX_TOKENS * 1.5)
    if (hasTable(sectionContent)) {
      // Guardar chunk anterior si existe
      if (currentChunk.trim() && currentTokens >= MIN_TOKENS) {
        chunks.push(createChunkObject(
          currentChunk.trim(),
          ++chunkNumber,
          convenioId,
          convenioNombre,
          currentSeccion,
          currentArticulo
        ));
        currentChunk = '';
        currentTokens = 0;
      }

      // Tabla como chunk independiente
      if (sectionTokens <= MAX_TOKENS * 1.5) {
        chunks.push(createChunkObject(
          sectionContent,
          ++chunkNumber,
          convenioId,
          convenioNombre,
          currentSeccion,
          currentArticulo,
          true // isTable
        ));
      } else {
        // Tabla muy grande: dividir por filas
        const lines = sectionContent.split('\n');
        let tableChunk = '';
        let tableTokens = 0;

        for (const line of lines) {
          const lineTokens = estimateTokens(line);

          if (tableTokens + lineTokens > MAX_TOKENS && tableChunk) {
            chunks.push(createChunkObject(
              tableChunk.trim(),
              ++chunkNumber,
              convenioId,
              convenioNombre,
              currentSeccion,
              currentArticulo,
              true
            ));
            tableChunk = line + '\n';
            tableTokens = lineTokens;
          } else {
            tableChunk += line + '\n';
            tableTokens += lineTokens;
          }
        }

        // Último chunk de tabla
        if (tableChunk.trim()) {
          chunks.push(createChunkObject(
            tableChunk.trim(),
            ++chunkNumber,
            convenioId,
            convenioNombre,
            currentSeccion,
            currentArticulo,
            true
          ));
        }
      }
      continue;
    }

    // CASO 2: Añadir a chunk actual si cabe
    if (currentTokens + sectionTokens <= TARGET_TOKENS) {
      currentChunk += (currentChunk ? '\n\n' : '') + sectionContent;
      currentTokens += sectionTokens;
      continue;
    }

    // CASO 3: Sección completa como nuevo chunk (si es razonable)
    if (sectionTokens >= MIN_TOKENS && sectionTokens <= MAX_TOKENS) {
      // Guardar chunk anterior
      if (currentChunk.trim() && currentTokens >= MIN_TOKENS) {
        chunks.push(createChunkObject(
          currentChunk.trim(),
          ++chunkNumber,
          convenioId,
          convenioNombre,
          currentSeccion,
          currentArticulo
        ));
      }

      // Nueva sección como chunk
      chunks.push(createChunkObject(
        sectionContent,
        ++chunkNumber,
        convenioId,
        convenioNombre,
        currentSeccion,
        currentArticulo
      ));

      currentChunk = '';
      currentTokens = 0;
      continue;
    }

    // CASO 4: Sección muy grande → dividir por párrafos
    if (sectionTokens > MAX_TOKENS) {
      // Guardar chunk anterior
      if (currentChunk.trim() && currentTokens >= MIN_TOKENS) {
        chunks.push(createChunkObject(
          currentChunk.trim(),
          ++chunkNumber,
          convenioId,
          convenioNombre,
          currentSeccion,
          currentArticulo
        ));
        currentChunk = '';
        currentTokens = 0;
      }

      // Dividir sección en párrafos
      const paragraphs = sectionContent.split(/\n\n+/);

      for (const para of paragraphs) {
        const paraTokens = estimateTokens(para);

        if (currentTokens + paraTokens <= TARGET_TOKENS) {
          currentChunk += (currentChunk ? '\n\n' : '') + para;
          currentTokens += paraTokens;
        } else {
          // Guardar chunk actual
          if (currentChunk.trim() && currentTokens >= MIN_TOKENS) {
            chunks.push(createChunkObject(
              currentChunk.trim(),
              ++chunkNumber,
              convenioId,
              convenioNombre,
              currentSeccion,
              currentArticulo
            ));
          }

          // Empezar nuevo chunk con overlap
          const overlap = getOverlap(currentChunk);
          currentChunk = overlap + (overlap ? '\n\n' : '') + para;
          currentTokens = estimateTokens(currentChunk);
        }
      }
    }
  }

  // Guardar último chunk
  if (currentChunk.trim() && currentTokens >= MIN_TOKENS) {
    chunks.push(createChunkObject(
      currentChunk.trim(),
      ++chunkNumber,
      convenioId,
      convenioNombre,
      currentSeccion,
      currentArticulo
    ));
  }

  // Actualizar total_chunks en todos
  const totalChunks = chunks.length;
  chunks.forEach(c => c.metadata.total_chunks = totalChunks);

  return chunks;
}

/**
 * Crear objeto chunk con metadata
 */
function createChunkObject(content, number, convenioId, convenioNombre, seccion, articulo, isTable = false) {
  const tokens = estimateTokens(content);
  const tipo = isTable ? 'tabla_salarial' : detectChunkType(content);

  return {
    contenido: content,
    metadata: {
      convenio_id: convenioId,
      convenio_nombre: convenioNombre,
      numero_chunk: number,
      tokens: tokens,
      seccion: seccion,
      articulo: articulo,
      tipo: tipo,
      tiene_tabla: isTable,
      total_chunks: 0 // Se actualiza después
    }
  };
}

/**
 * Obtener overlap del final del chunk anterior
 */
function getOverlap(text) {
  if (!text || text.length < OVERLAP_CHARS) return '';

  // Buscar un punto de corte natural (fin de oración)
  const endPortion = text.substring(text.length - OVERLAP_CHARS * 1.5);
  const sentenceEnd = endPortion.lastIndexOf('. ');

  if (sentenceEnd > 0) {
    return endPortion.substring(sentenceEnd + 2);
  }

  // Si no hay punto, cortar en espacio
  const spaceIndex = endPortion.indexOf(' ');
  if (spaceIndex > 0) {
    return endPortion.substring(spaceIndex + 1);
  }

  return endPortion;
}

// ============================================
// EJECUCIÓN PRINCIPAL
// ============================================

// Obtener datos del convenio guardado (viene del nodo anterior)
const inputData = $input.first().json;

// La respuesta de Supabase es un array con el convenio insertado
const convenioData = Array.isArray(inputData) ? inputData[0] : inputData;

if (!convenioData || !convenioData.id) {
  throw new Error('No se pudo obtener el ID del convenio guardado. Data: ' + JSON.stringify(inputData));
}

const convenioId = convenioData.id; // UUID real del convenio
const convenioNombre = convenioData.nombre;
const markdown = convenioData.markdown_completo || '';

// Validar input
if (!markdown || markdown.length < 100) {
  throw new Error('Markdown vacío o muy corto para procesar. Longitud: ' + markdown.length);
}

// Ejecutar chunking
const chunks = chunkMarkdown(markdown, convenioId, convenioNombre);

// Estadísticas
const stats = {
  total_chunks: chunks.length,
  avg_tokens: Math.round(chunks.reduce((sum, c) => sum + c.metadata.tokens, 0) / chunks.length),
  min_tokens: Math.min(...chunks.map(c => c.metadata.tokens)),
  max_tokens: Math.max(...chunks.map(c => c.metadata.tokens)),
  con_tablas: chunks.filter(c => c.metadata.tiene_tabla).length,
  tipos: {}
};

// Contar tipos
chunks.forEach(c => {
  stats.tipos[c.metadata.tipo] = (stats.tipos[c.metadata.tipo] || 0) + 1;
});

// Retornar chunks como items individuales para procesamiento en lote
return chunks.map((chunk, index) => ({
  json: {
    contenido: chunk.contenido,
    convenio_id: chunk.metadata.convenio_id,
    metadata: chunk.metadata,
    // Añadir stats solo al primer item para referencia
    ...(index === 0 ? { chunking_stats: stats } : {})
  }
}));

// Obtener todos los chunks generados
const chunks = $input.all();

// Preparar array para pasar al siguiente nodo (Generate Embeddings)
const allChunks = chunks.map(item => ({
  convenio_id: item.json.convenio_id,
  contenido: item.json.contenido,
  metadata: item.json.metadata
}));

// Obtener stats del primer chunk (si existe)
const stats = chunks[0]?.json?.chunking_stats || {
  total_chunks: chunks.length,
  avg_tokens: 0,
  min_tokens: 0,
  max_tokens: 0
};

return [{
  json: {
    chunks: allChunks,
    total_chunks: allChunks.length,
    stats: stats,
    convenio_id: chunks[0]?.json?.convenio_id
  }
}];

// ============================================
// NODO: Prepare Batch for OpenAI
// TIPO: Code (JavaScript)
// FASE: I1.8
// POSICIÓN: Después de "Prepare Chunks for Insert"
// ============================================

// Obtener datos del input
const inputData = $input.first().json;
const chunks = inputData.chunks;

// Validar que hay chunks
if (!chunks || chunks.length === 0) {
  throw new Error('No hay chunks para generar embeddings');
}

// Preparar textos para embedding
const textos = chunks.map(c => c.contenido);

console.log(`Preparando ${chunks.length} chunks para OpenAI Embeddings API...`);

// Retornar payload separado para OpenAI y metadata interna
return [{
  json: {
    // Payload limpio para OpenAI (solo campos requeridos por la API)
    openai_payload: {
      input: textos,
      model: 'text-embedding-3-small',
      encoding_format: 'float'
    },

    // Metadatos internos (NO se envían a OpenAI)
    _chunks_original: chunks,
    _total_chunks: chunks.length,
    _convenio_id: inputData.convenio_id,
    _stats: inputData.stats
  }
}];

// ============================================
// NODO: Merge Embeddings with Chunks
// TIPO: Code (JavaScript)
// FASE: I1.8
// POSICIÓN: Después de "HTTP Request OpenAI Embeddings"
// ============================================

// Obtener respuesta de OpenAI del nodo HTTP anterior
const inputItem = $input.first();
if (!inputItem) {
  throw new Error('No se recibió respuesta del nodo HTTP de OpenAI');
}
const openAIResponse = inputItem.json;

// Obtener chunks originales que pasamos desde "Prepare Batch for OpenAI"
const prepareNodeItem = $('Prepare Batch for OpenAI').first();
if (!prepareNodeItem) {
  throw new Error(
    'No se encontraron datos del nodo "Prepare Batch for OpenAI"'
  );
}
const prepareNode = prepareNodeItem.json;
const chunks = prepareNode._chunks_original;
const convenioId = prepareNode._convenio_id;

if (!chunks || !Array.isArray(chunks)) {
  throw new Error('Chunks originales no encontrados o formato inválido');
}

// Validar que OpenAI retornó los embeddings
if (!openAIResponse.data || !Array.isArray(openAIResponse.data)) {
  throw new Error('Respuesta inválida de OpenAI API: falta campo "data"');
}

const embeddings = openAIResponse.data;

// Validar que hay chunks para procesar
if (!chunks || chunks.length === 0) {
  throw new Error('No hay chunks para combinar con embeddings');
}

// Validar que la cantidad coincide
if (embeddings.length !== chunks.length) {
  throw new Error(
    `Mismatch en embeddings: ${chunks.length} chunks pero ${embeddings.length} embeddings recibidos`
  );
}

// Combinar chunks con sus embeddings (defensivamente)
const chunksWithEmbeddings = chunks.map((chunk, index) => ({
  ...chunk,
  embedding: (embeddings[index] && embeddings[index].embedding) || null
}));

// Validar que al menos un embedding tiene la dimensión correcta (1536 para text-embedding-3-small)
const firstNonEmptyEmbedding = chunksWithEmbeddings.find(c =>
  Array.isArray(c.embedding)
);

if (!firstNonEmptyEmbedding) {
  throw new Error(
    'No se encontraron embeddings válidos. Todos los chunks tienen embeddings nulos o indefinidos.'
  );
}

if (firstNonEmptyEmbedding.embedding.length !== 1536) {
  throw new Error(
    `Embedding dimension incorrecta: esperado 1536, recibido ${firstNonEmptyEmbedding.embedding.length}`
  );
}

// Advertir si hay chunks sin embeddings
const chunksWithoutEmbeddings = chunksWithEmbeddings.filter(
  c => !Array.isArray(c.embedding)
);
if (chunksWithoutEmbeddings.length > 0) {
  console.warn(
    `⚠️ ${chunksWithoutEmbeddings.length} chunks sin embeddings válidos`
  );
}

// Calcular estadísticas de uso
const usage = openAIResponse.usage || {};
const embeddingUsage = {
  total_tokens: usage.total_tokens || 0,
  prompt_tokens: usage.prompt_tokens || 0,
  chunks_processed: chunks.length,
  model: openAIResponse.model || 'text-embedding-3-small',
  estimated_cost_usd: ((usage.total_tokens || 0) / 1000000) * 0.02 // $0.02 por 1M tokens
};

console.log(`✓ Embeddings generados exitosamente:`);
console.log(`  - Chunks procesados: ${embeddingUsage.chunks_processed}`);
console.log(`  - Tokens consumidos: ${embeddingUsage.total_tokens}`);
console.log(
  `  - Coste estimado: $${embeddingUsage.estimated_cost_usd.toFixed(6)}`
);

// Preparar array para insert en Supabase con validación de metadata
const insertData = chunksWithEmbeddings
  .map((chunk, index) => {
    // Validar que el chunk tiene metadata válida
    if (!chunk.metadata || typeof chunk.metadata !== 'object') {
      console.warn(
        `⚠️ Chunk ${index} carece de metadata válida, usando valores por defecto`
      );
      return {
        convenio_id: chunk.convenio_id,
        contenido: chunk.contenido,
        chunk_index: index, // Usar índice del array como fallback
        metadata: { numero_chunk: index, warning: 'metadata_missing' },
        embedding: chunk.embedding
      };
    }

    // Validar que numero_chunk existe
    const chunkIndex =
      typeof chunk.metadata.numero_chunk === 'number'
        ? chunk.metadata.numero_chunk
        : index; // Fallback al índice si no existe

    if (typeof chunk.metadata.numero_chunk !== 'number') {
      console.warn(
        `⚠️ Chunk ${index} carece de numero_chunk, usando índice ${index}`
      );
    }

    return {
      convenio_id: chunk.convenio_id,
      contenido: chunk.contenido,
      chunk_index: chunkIndex,
      metadata: chunk.metadata,
      embedding: chunk.embedding // IMPORTANTE: Incluir el embedding
    };
  })
  .filter(chunk => chunk !== null); // Filtrar chunks nulos si hubiese alguno

// Contar chunks con embeddings válidos de 1536 dimensiones
const validEmbeddingsCount = insertData.filter(
  item =>
    item.embedding &&
    Array.isArray(item.embedding) &&
    item.embedding.length === 1536
).length;

console.log(
  `✓ Preparados ${insertData.length} chunks para inserción en Supabase`
);

// Log condicional basado en embeddings válidos
if (validEmbeddingsCount === insertData.length) {
  console.log(`  - Todos los chunks tienen embeddings de dimensión 1536`);
} else {
  console.log(
    `  - ${validEmbeddingsCount}/${insertData.length} chunks con embeddings válidos de 1536 dimensiones`
  );
  console.log(
    `  - ⚠️ ${insertData.length - validEmbeddingsCount} chunks con embeddings faltantes o inválidos`
  );
}

return [{
  json: {
    chunks: insertData,
    total_chunks: insertData.length,
    embedding_usage: embeddingUsage,
    convenio_id: convenioId
  }
}];

// ============================================
// NODO: Chunks Branch Complete
// Pasar confirmación de que la rama de chunks terminó
// ============================================

const chunksData = $('Merge Embeddings with Chunks').first().json;

console.log('✓ Rama de chunks completada: ' + chunksData.total_chunks + ' chunks insertados');

return [{
  json: {
    branch: 'chunks',
    status: 'completed',
    total_chunks: chunksData.total_chunks,
    timestamp: Date.now()
  }
}];

// ============================================
// NODO: Prepare Response (ACTUALIZADO I1.9)
// Recoge datos de ambas ramas: chunks + perfil
// ============================================

const convenioData = $('Save md in supabase1').first().json;
const markdownData = $('Extract and clean md1').first().json;
const chunksData = $('Merge Embeddings with Chunks').first().json;

// Intentar obtener datos del perfil (puede no existir si esa rama falló)
let perfilData = null;
try {
  perfilData = $('Upsert Perfil Supabase').first().json;
} catch (e) {
  console.log('⚠ Rama de perfil no disponible (posible error): ' + e.message);
}

// Construir response
const response = {
  status: 'success',
  message: 'Convenio procesado correctamente con embeddings' + (perfilData ? ' y perfil JSON' : ''),
  data: {
    convenio_id: convenioData.id,
    nombre: convenioData.nombre,
    codigo_regcon: convenioData.codigo_regcon,
    markdown_length: markdownData.longitud,
    pdf_url: convenioData.url_pdf,
    chunks_generados: chunksData.total_chunks,
    embeddings_generados: chunksData.total_chunks,
    embedding_usage: chunksData.embedding_usage || {}
  }
};

// Añadir info del perfil si existe
if (perfilData) {
  response.data.perfil = {
    perfil_id: perfilData.perfil_id,
