    is_valid: perfilData.validation?.is_valid || false,
    claude_usage: perfilData.claude_usage || {}
  };
} else {
  response.data.perfil = {
    status: 'skipped_or_failed',
    message: 'La extracción de perfil JSON no se completó. Los chunks y embeddings se procesaron correctamente.'
  };
}

return [{ json: response }];

// Obtener la respuesta de LlamaParse
const llamaParseResult = $input.first().json;

