const REQUIRED_FIELDS = ['convenio', 'ambito', 'variables_criticas', 'categorias_profesionales', 'jornada'];
const VALID_AMBITOS = ['estatal', 'autonomico', 'provincial', 'empresa'];
const VALID_COMPLEMENTO_TIPOS = ['porcentaje', 'cantidad_fija', 'trienio', 'quinquenio', 'bienio', 'otro'];

function cleanJsonResponse(text) {
  let cleaned = text.trim();
  if (cleaned.startsWith('```json')) cleaned = cleaned.slice(7);
  else if (cleaned.startsWith('```')) cleaned = cleaned.slice(3);
  if (cleaned.endsWith('```')) cleaned = cleaned.slice(0, -3);
  return cleaned.trim();
}

function validateCategoria(cat, index) {
  const warnings = [];
  if (!cat.nombre || typeof cat.nombre !== 'string') {
    warnings.push(`categorias_profesionales[${index}]: falta "nombre"`);
  }
  if (typeof cat.salario_base_anual === 'number') {
    cat.salario_base_anual = Math.round(cat.salario_base_anual * 100) / 100;
  }
  if (typeof cat.salario_base_mensual === 'number') {
    cat.salario_base_mensual = Math.round(cat.salario_base_mensual * 100) / 100;
  }
  return warnings;
}

function validateComplemento(comp, index) {
  const warnings = [];
  if (!comp.nombre) warnings.push(`complementos[${index}]: falta "nombre"`);
  if (comp.tipo && !VALID_COMPLEMENTO_TIPOS.includes(comp.tipo)) {
    warnings.push(`complementos[${index}].tipo "${comp.tipo}" no válido, cambiado a "otro"`);
    comp.tipo = 'otro';
  }
  return warnings;
}

// MAIN
const inputData = $input.first().json;

// Check si el nodo anterior falló (continueOnFail)
if (inputData.error) {
  console.log('⚠ El nodo Extract Perfil Claude falló: ' + (inputData.error.message || JSON.stringify(inputData.error)));
  return [{
    json: {
      perfil_data: null,
      convenio_id: null,
      convenio_nombre: null,
      validation: { is_valid: false, error: inputData.error.message || 'Error en extracción' },
      claude_usage: null
    }
  }];
}

const rawResponse = inputData.raw_response;
const convenioId = inputData.convenio_id;
const convenioNombre = inputData.convenio_nombre;
const claudeUsage = inputData.claude_usage;

if (!rawResponse) {
  throw new Error('No hay respuesta de Claude para validar');
}

const cleanedJson = cleanJsonResponse(rawResponse);
let perfil;

try {
  perfil = JSON.parse(cleanedJson);
} catch (parseError) {
  // Intentar extraer JSON usando brace-matching
  const firstBrace = cleanedJson.indexOf('{');

  if (firstBrace !== -1) {
    // Implementar brace-matching para extraer el primer objeto JSON válido
    let braceCount = 0;
    let endIndex = -1;
    let inString = false;
    let escapeNext = false;

    for (let i = firstBrace; i < cleanedJson.length; i++) {
      const char = cleanedJson[i];

      // Manejar escape characters
      if (escapeNext) {
        escapeNext = false;
        continue;
      }

      if (char === '\\') {
        escapeNext = true;
        continue;
      }

      // Manejar strings (ignorar braces dentro de strings)
      if (char === '"') {
        inString = !inString;
        continue;
      }

      if (inString) continue;

      // Contar braces fuera de strings
      if (char === '{') {
        braceCount++;
      } else if (char === '}') {
        braceCount--;
        if (braceCount === 0) {
          endIndex = i + 1;
          break;
        }
      }
    }

    if (endIndex !== -1) {
      const extractedJson = cleanedJson.substring(firstBrace, endIndex);
      try {
        perfil = JSON.parse(extractedJson);
        console.log('⚠ JSON extraído usando brace-matching');
      } catch (e) {
        // Debug log con contenido sanitizado
        const sanitizedPreview = cleanedJson.substring(0, 100).replace(/[^\x20-\x7E]/g, '?');
        console.log(`Debug: Parse error after brace-matching. Error: ${parseError.message}. Preview: ${sanitizedPreview}...`);
        throw new Error(`Invalid JSON from Claude: ${parseError.message}`);
      }
    } else {
      const sanitizedPreview = cleanedJson.substring(0, 100).replace(/[^\x20-\x7E]/g, '?');
      console.log(`Debug: No matching closing brace found. Preview: ${sanitizedPreview}...`);
      throw new Error('No valid JSON found in Claude response');
    }
  } else {
    const sanitizedPreview = cleanedJson.substring(0, 100).replace(/[^\x20-\x7E]/g, '?');
    console.log(`Debug: No opening brace found. Preview: ${sanitizedPreview}...`);
    throw new Error('No valid JSON found in Claude response');
  }
}

console.log('✓ JSON parseado correctamente');

const missingFields = REQUIRED_FIELDS.filter(f => !perfil[f]);
if (missingFields.length > 0) console.log(`⚠ Campos faltantes: ${missingFields.join(', ')}`);

const allWarnings = [];

if (Array.isArray(perfil.categorias_profesionales)) {
  perfil.categorias_profesionales.forEach((cat, i) => allWarnings.push(...validateCategoria(cat, i)));
  console.log(`✓ ${perfil.categorias_profesionales.length} categorías profesionales`);
}

if (Array.isArray(perfil.complementos)) {
  perfil.complementos.forEach((comp, i) => allWarnings.push(...validateComplemento(comp, i)));
  console.log(`✓ ${perfil.complementos.length} complementos`);
}

if (Array.isArray(perfil.variables_criticas)) {
  console.log(`✓ Variables críticas: ${perfil.variables_criticas.join(', ')}`);
}

const validationResult = {
  is_valid: missingFields.length === 0,
  missing_fields: missingFields,
  warnings: allWarnings,
  stats: {
    categorias: Array.isArray(perfil.categorias_profesionales) ? perfil.categorias_profesionales.length : 0,
    complementos: Array.isArray(perfil.complementos) ? perfil.complementos.length : 0,
    variables_criticas: Array.isArray(perfil.variables_criticas) ? perfil.variables_criticas.length : 0,
    tiene_jornada: !!perfil.jornada,
    tiene_horas_extra: !!perfil.horas_extra,
    tiene_periodo_prueba: Array.isArray(perfil.periodo_prueba) && perfil.periodo_prueba.length > 0,
    tiene_vacaciones: !!perfil.vacaciones,
    tiene_tablas_salariales: !!perfil.tablas_salariales
  }
};

console.log(`✓ Validación: ${validationResult.is_valid ? 'OK' : 'CON CAMPOS FALTANTES'}`);

return [{
  json: {
    perfil_data: perfil,
    convenio_id: convenioId,
    convenio_nombre: convenioNombre,
    validation: validationResult,
    claude_usage: claudeUsage
  }
}];

